import h5py
import numpy as np

def read_str_array(node):
    if isinstance(node, h5py.Group):
        if node.attrs.get('encoding-type') == 'nullable-string-array':
            values = node['values'][...]
            mask = node['mask'][...]
            return [ (None if not m else v) for v,m in zip(values, mask)]
        raise Exception(node.attrs)
    return node[...]

for name in ['plate_a','plate_b','plate_c']:
    path = f'fixtures/study_panel/{name}.h5ad'
    with h5py.File(path, 'r') as f:
        obs_idx = read_str_array(f['obs/_index'])
        var_idx = read_str_array(f['var/_index'])
        print(name, 'obs_idx=', obs_idx, 'var_idx=', var_idx)
        if 'batch' in f['obs']:
            b = f['obs/batch']
            if b.attrs.get('encoding-type')=='categorical':
                cats = read_str_array(b['categories'])
                print('   batch cat:', cats, 'codes:', b['codes'][...])
            else:
                print('   batch:', read_str_array(b))
        if 'quality' in f['obs']:
            print('   quality:', f['obs/quality'][...])
        if 'panel' in f['var']:
            print('   panel:', read_str_array(f['var/panel']))
        print('   X:', f['X'][...])
"

