def _apply_to_array(self, el, *, axis, fill_value=None):
    if fill_value is None:
        fill_value = default_fill_value([el])
    if el.shape[axis] == 0:
        # Presumably faster since it won't allocate the full array
        shape = list(el.shape)
        shape[axis] = len(self.new_idx)
        return np.broadcast_to(fill_value, tuple(shape))

    indexer = self.old_idx.get_indexer(self.new_idx)

    # Indexes real fast, and does outer indexing.
    # `pd.api.extensions.take` requires a numpy array (or extension
    # array); disk-backed containers such as `h5py.Dataset` implement
    # the array protocol but have no `.take` method, so load them first.
    # Memory usage is bounded by the element itself, which keeps this
    # practical for large studies.
    arr = el if isinstance(el, np.ndarray) else np.asarray(el)
    return pd.api.extensions.take(
        arr, indexer, axis=axis, allow_fill=True, fill_value=fill_value
    )

